    // The heading is usually a sibling or parent of the anchor
    let heading = discographyAnchor.closest('h2');
    if (!heading) {
        // Sometimes the anchor is inside the h2
        heading = discographyAnchor.parentElement;
    }

    // Find the next element with class 'mw-headline' or similar
    // Actually, get all elements after heading until next h2
    const result = [];
    let current = heading;
    while (current.nextElementSibling) {
